import{_ as t,o as s,c as o,j as e,a as n}from"./chunks/framework.QCr1ZR1X.js";const _=JSON.parse('{"title":"思维导图-第4章-边缘计算","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第4章-边缘计算.md","filePath":"mindmap/思维导图-第4章-边缘计算.md","lastUpdated":1786967935000}'),d={name:"mindmap/思维导图-第4章-边缘计算.md"};function r(i,a,L,C,l,P){return s(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"思维导图-第4章-边缘计算",tabindex:"-1"},[n("思维导图-第4章-边缘计算 "),e("a",{class:"header-anchor",href:"#思维导图-第4章-边缘计算","aria-label":'Permalink to "思维导图-第4章-边缘计算"'},"​")],-1),e("div",{class:"mermaid"},'# 第4章 边缘计算 — 思维导图 ## 4.1 数据都往云端传，行得通吗 - 海上风电场：500GB/天，卫星带宽有限 - SMT产线：1.5GB/秒，光纤成本高 - 延迟问题：云端离设备数百公里，往返几十毫秒 ## 4.2 边缘计算：在数据源头做第一轮处理 ### 四个核心驱动力（省·快·稳·密） - 省（带宽成本） - 99%普通数据就地过滤 - 有价值数据才上传 - 快（延迟要求） - 毫秒级本地决策 - 危险紧急停止不能等云端 - 稳（离线可靠性） - 本地自治，断网续传 - 网络恢复后补传 - 密（数据隐私） - 敏感数据不出厂 - 核心工艺参数本地处理 ### 边缘与云的互补关系 - 边缘：做快决策（毫秒级实时判断） - 云：做深训练（海量历史数据训练AI模型） - 正反馈循环：边缘执行 → 云端训练 → 模型下发 → 边缘更准 ## 4.3 边缘计算的系统架构 ### 三层架构 - 边缘网关（工控机/智能路由器） - 协议转换 + 数据预处理 + 断网缓存 - 边缘服务器（GPU工控PC） - AI推理10-50ms - 50路高清相机缺陷检测 - 云端（全量历史数据存储） - AI模型训练 + 全局调度 ### 与ISA-95/IIRA对应 - 现场设备 → L0-L1 → 边缘层 - 边缘网关 → L1-L2之间 → 边缘层 - 边缘服务器 → L2附近 → 边缘层与平台层之间 - 云端 → L3-L4 → 平台层+应用层+业务层 ### 功能视角 vs 部署视角 - IIRA：功能视角（数据在哪个环节被怎样处理） - 三层架构：部署视角（设备装在哪里、算力多强） ## 4.4 走近软PLC：当控制变成软件 ### 硬PLC vs 软PLC - 硬PLC - 专用硬件+厂商定制实时操作系统 - 优点：稳定（十年不重启） - 缺点：硬件绑定（每家用自己的编程软件） - 软PLC - 控制逻辑纯软件化，运行在通用工控机上 - TwinCAT/Codesys/SIMATIC 软件控制器 - 软PLC与边缘计算的关系 - 同一台工控机：软PLC控制传送带 + Node-RED分析振动 - 控制和分析不再分家 ### 软PLC ≠ 安全PLC - 软PLC：管"干活"（控制逻辑软件化） - 安全PLC：管"保命" - 急停/安全门联锁/安全光幕 - IEC 61508（功能安全） - ISO 13849（机械安全） - SIL/PL等级认证 - 安全PLC永远不能软件化 ### 三种边缘计算典型工作模式 - 数据预处理：滑动均值消除噪声 - 本地决策：阈值判断立即报警 - 数据筛选上传：异常才上传原始数据，正常只传摘要 ## 4.5 动手实践：用Node-RED构建边缘数据处理流 ### 实践任务 - 用Function节点编写JavaScript模拟传感器 - 温度+振动，每秒一组 - 5%概率异常高温，3%概率振动尖峰 - 本地实时判断 - Switch节点温度>80℃立即报警 - Debug节点输出 - 数据预处理 - 滑动均值（context.dataBuffer缓存10个数据点） - 每30秒输出一次均值摘要 ## 4.6 动手实践：数据筛选对比 + 软PLC初体验 ### 实践任务 - 添加振动异常判断 - Switch节点>3mm/s - 原始数据打包上传 - 用计数器看数据量对比 - Debug节点消息计数 - 全量120条 vs 筛选后约14-21条 - 减少约85% - 安装并体验OpenPLC - git clone + install.sh linux - 上传hello_world.st示例程序 - 启动PLC - Node-RED通过ModbusTCP读取PLC变量 - 端口502，FC03，地址0 - 每1秒轮询 ## 🎯 课程思政 - 在边缘处创新——中国方案的自主突围 - 过去：核心芯片依赖进口、工控操作系统多为国外产品 - 现在：华为Atlas（昇腾AI芯片）、研华科技、5G MEC、国产工控操作系统 - 边缘计算领域必须走自主创新之路，守住工业互联网安全底线',-1)])])}const m=t(d,[["render",r]]);export{_ as __pageData,m as default};
